import sys

data = sys.stdin.read().split()
n, amount = int(data[0]), int(data[1])
coins = [int(x) for x in data[2:2 + n]]
seen = {0}
frontier = [0]
steps = 0
ans = -1
if amount == 0:
    ans = 0
else:
    while frontier:
        steps += 1
        nxt = []
        for v in frontier:
            for c in coins:
                w = v + c
                if w <= amount and w not in seen:
                    seen.add(w)
                    nxt.append(w)
        if amount in seen:
            ans = steps
            break
        frontier = nxt
print(ans)

